export function getServiceArea(slug: string): ServiceArea | undefined {
  return serviceAreas.find((a) => a.slug === slug)
}

// Schema comes from the shared BUSINESS_CONFIG (schema-business.ts) via the
// generic schema-builder library — never hardcode business name/phone/address
// here. The root layout already renders the sitewide LocalBusiness + WebSite
// nodes once, so includeSitewide: false avoids building a second, competing
// copy of them on every service-area page (see schema-builder's own warning
// about @id drift when a second LocalBusiness node is built independently).
export function generateServiceAreaSchema(area: ServiceArea) {
  const { jsonLd } = buildServiceAreaSchema(
    BUSINESS_CONFIG,
    {
      city: area.city,
      state: 'Texas',
      stateCode: area.state,
      slug: area.slug,
      description: area.intro,
      pageTitle: `${area.city}, ${area.state} Roofing & Construction | KingdomCare`,
      faqs: area.faqs,
    },
    { includeSitewide: false, strict: false },
  )
  return jsonLd
}
